import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds exact halves to the even cent so totals don't drift upward", () => {
    expect(roundCents(122.5)).toBe(122);
    expect(roundCents(123.5)).toBe(124);
    expect(roundCents(0.5)).toBe(0);
  });

  it("rounds non-halves to the nearest cent", () => {
    expect(roundCents(122.49)).toBe(122);
    expect(roundCents(122.51)).toBe(123);
    expect(roundCents(122)).toBe(122);
  });

  it("treats refunds (negative amounts) symmetrically", () => {
    expect(roundCents(-122.5)).toBe(-122);
    expect(roundCents(-123.5)).toBe(-124);
    expect(roundCents(-122.51)).toBe(-123);
  });
});

